mapper.select:
SELECT pet_seq, user_seq, pet_name, pet_type, pet_age, gender, birth_date, pet_image, memo, created_at, updated_at
FROM pet
WHERE pet_seq = #{petSeq} AND user_seq = #{userSeq}

SELECT
	pet_seq, user_seq, pet_name, pet_type, pet_age, pet_image, created_at, updated_at
FROM pet
WHERE user_seq = #{userSeq}
ORDER BY pet_seq DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM pet
WHERE user_seq = #{userSeq}
